package com.wizzadrds.theworldremembers.rumor; import com.mojang.serialization.Codec; import net.minecraft.resources.Identifier; import net.minecraft.server.MinecraftServer; import net.minecraft.server.level.ServerLevel; import net.minecraft.world.level.saveddata.SavedData; import net.minecraft.world.level.saveddata.SavedDataType; import java.util.*; public final class ConversationManager extends SavedData{private final List<Conversation> conversations=new ArrayList<>();private static final Codec<ConversationManager>C=Conversation.CODEC.listOf().xmap(l->{var x=new ConversationManager();x.conversations.addAll(l);return x;},x->x.conversations);private static final SavedDataType<ConversationManager>TYPE=new SavedDataType<>(Identifier.fromNamespaceAndPath("the_world_remembers","conversations"),ConversationManager::new,C,null);public static ConversationManager get(MinecraftServer s){ServerLevel l=s.getLevel(ServerLevel.OVERWORLD);return l==null?new ConversationManager():l.getDataStorage().computeIfAbsent(TYPE);}public void record(Conversation c){conversations.add(c);while(conversations.size()>1024)conversations.remove(0);setDirty();}public List<Conversation> all(){return List.copyOf(conversations);}}
